const draft={open:false,step:0,mode:'Monthly',name:'',website:'',owner:'Abel Miranda',start:'2026-10-01',launch:'',hours:20,hoursCommitment:'committed_hours',content:4,gbp:false,gbpPosting:'Social team / Sprout',gbpHours:false,listings:false,listingsProvider:'GHL / Yext',prepBudget:'Separate onboarding effort',prepExpanded:false,plan:'Local SEO launch',budget:30,end:'2026-12-31',source:'plan',basecampLoaded:false,project:'Evergreen Dental · SEO',basecampIds:[],planIds:['audit','research'],manual:[],error:'',created:null,savedClient:null,view:'list',notice:''};
const planTasks=[{id:'audit',title:'Run technical baseline audit',hours:6},{id:'research',title:'Map local keyword opportunities',hours:4},{id:'plan',title:'Draft first 90-day SEO plan',hours:3}];
const basecampTasks=[{id:'bc-101',title:'Fix service-page title tags',hours:2},{id:'bc-102',title:'Review local citation accuracy',hours:3},{id:'bc-103',title:'Update appointment conversion tracking',hours:2}];
const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function rerender(){let active=document.activeElement;let key=active?.dataset.field;let action=active?.dataset.action;document.getElementById('stage').innerHTML=variants[current]();if(draft.open){let target=key?document.querySelector(`[data-field="${key}"]`):action?document.querySelector(`.modal [data-action="${action}"]`):null;(target||document.querySelector('.modal .close'))?.focus();}}
function tasks(){return [...planTasks.filter(t=>draft.planIds.includes(t.id)&&draft.plan!=='Blank plan'),...basecampTasks.filter(t=>draft.basecampIds.includes(t.id)),...draft.manual];}
function app(modal){let c=draft.savedClient||draft.created;return `<div class="app" ${draft.open?'inert':''}><aside class="sidebar"><div class="brand">SEO <b>Ops</b> Center</div><div class="nav-label">AGENCY WORKSPACE</div><div class="nav">◫ &nbsp; Dashboard</div><div class="nav active">▣ &nbsp; Clients</div><div class="nav">✓ &nbsp; Tasks</div><div class="nav">▤ &nbsp; Deliverables</div><div class="nav">◷ &nbsp; Reports</div></aside><main class="workspace"><div class="workspace-header"><div><h1>${draft.view==='list'?'Clients':safe(c?.name||'Client workspace')}</h1><span class="muted">${draft.view==='list'?'Manage your relationships and delivery.':'Your setup is ready in the existing workspace.'}</span></div><button class="primary" data-action="open">＋ New Client</button></div>${draft.view==='list'?`<div class="tabs"><span>Active clients</span><span>Archived</span></div><table class="client-table"><thead><tr><th>Client</th><th>Engagement</th><th>Account manager</th><th>Status</th></tr></thead><tbody>${c?`<tr><td><button data-action="view" data-view="Overview"><span class="avatar">${safe(c.name.slice(0,2).toUpperCase())}</span>${safe(c.name)}</button></td><td>${c.mode}</td><td>${safe(c.owner)}</td><td><span class="badge pink">Onboarding</span></td></tr>`:''}<tr><td><span class="avatar">RC</span>Riverside Chiropractic</td><td>Monthly</td><td>Abel Miranda</td><td><span class="badge green">Active</span></td></tr><tr><td><span class="avatar">SL</span>Summit Legal</td><td>Custom</td><td>Carlos Morones</td><td><span class="badge green">Active</span></td></tr></tbody></table>`:`<div class="tabs">${['Overview','SEO Plan','Tasks','Deliverables'].map(v=>`<button data-action="view" data-view="${v}" class="${draft.view===v?'secondary':''}">${v}</button>`).join('')}<button data-action="list">← Clients</button></div>${createdView()}`}<p class="prototype-note">Local prototype · no database writes or Basecamp connection · draft survives switching layouts</p></main></div>${draft.open?modal:''}`;}
function createdView(){const c=draft.savedClient||draft.created;if(!c)return '';if(draft.view==='Tasks')return `<section class="details-page"><h2>Tasks</h2>${c.tasks.length?`<ul>${c.tasks.map(t=>`<li>${safe(t.title)} <span class="badge">${t.id.startsWith('bc')?'Basecamp import':'SEO setup'}</span></li>`).join('')}</ul>`:'<p>No tasks added. You can add delivery tasks in this workspace.</p>'}</section>`;if(draft.view==='SEO Plan')return `<section class="details-page"><span class="badge pink">Draft</span><h2 style="margin-top:15px">${safe(c.plan)}</h2><p>${c.mode==='Monthly'?'Monthly SEO scope':'Custom scoped delivery'} · ${safe(c.name)}</p><p>Setup has initialized this demo plan. Continue drafting in the existing SEO Plan experience.</p><ul>${c.tasks.map(t=>`<li>${safe(t.title)}</li>`).join('')}</ul></section>`;return `<section class="details-page"><h2>${draft.view==='Deliverables'?'Planned services':'Client setup summary'}</h2>${summaryRows(c)}<p>Strategy preparation is tracked as onboarding effort. Recurring targets begin after the strategy meeting is held and launch is confirmed.</p></section>`;}
function modeChoices(compact=false){return `<div class="${compact?'mini-mode':'mode-cards'}">${['Monthly','Custom'].map(mode=>`<button class="${compact?'':'mode-card'}" data-mode="${mode}" aria-pressed="${draft.mode===mode}">${compact?`<b>${mode}</b><small>${mode==='Monthly'?'Ongoing SEO & content':'Scoped plan & tasks'}</small>`:`<span class="icon">${mode==='Monthly'?'↻':'◇'}</span><h3>${mode}</h3><p>${mode==='Monthly'?'A recurring SEO partnership with monthly hours, content and additional services.':'A scoped engagement built from an SEO plan, custom tasks or Basecamp work.'}</p><small>${mode==='Monthly'?'Hours + content + services':'Plan + tasks + imports'}</small>`}</button>`).join('')}</div>`;}
function input(label,key,type='text',help='',attrs=''){return `<label class="field">${label}<input data-field="${key}" type="${type}" value="${safe(draft[key])}" ${attrs}>${help?`<small>${help}</small>`:''}</label>`;}
function select(label,key,options,help=''){return `<label class="field">${label}<select data-field="${key}">${options.map(o=>`<option ${draft[key]===o?'selected':''}>${safe(o)}</option>`).join('')}</select>${help?`<small>${help}</small>`:''}</label>`;}
function details(){return `<div class="fields">${input('Client name *','name','text','','autocomplete="organization"')}${input('Website','website','url','Optional; e.g. https://evergreendental.com')}${select('Account manager','owner',['Abel Miranda','Carlos Morones'])}${input('Onboarding Date *','start','date','Strategy preparation and time tracking can start now.')}${input('Launched Date','launch','date','Optional during onboarding. Enter the actual launch date.')}</div>`;}
function monthly(){return `<div class="fields"><div>${input('SEO hours / month *','hours','number','','min="0" step="0.5"')}<label class="allowance-option"><input type="checkbox" data-allowance ${draft.hoursCommitment==='capacity'?'checked':''}><span class="allowance-copy"><span class="allowance-title">Treat as a monthly allowance</span><span class="allowance-description">Unused hours don’t count as a delivery shortfall.</span></span></label></div>${input('Content pieces / month *','content','number','Mixed content quota. Delivered counts toward fulfillment.','min="0" step="1"')}<label class="field">Service cadence<input value="Monthly" readonly></label></div><label class="service"><input type="checkbox" data-field="gbp" ${draft.gbp?'checked':''}><span class="grow"><strong>Google Business Profile management</strong><small>Initial optimization + ongoing management as needed.</small></span><span class="badge">Additional service</span></label>${draft.gbp?`<div class="fields" style="margin-top:15px"><label class="service" style="margin:0"><input type="checkbox" data-field="gbpHours" ${draft.gbpHours?'checked':''}><span><strong>Management uses SEO hours</strong><small>Track actual work; no automatic weekly SEO tasks.</small></span></label></div>`:''}<label class="service"><input type="checkbox" data-field="listings" ${draft.listings?'checked':''}><span class="grow"><strong>Directory Listings</strong><small>One-time activation + managed listings.</small></span><span class="badge">Additional service</span></label>${draft.listings?`<div class="callout">Setup: activate the service, verify business information and resolve exceptions. Track service status instead of 60 individual directory tasks.</div>`:''}<details class="accordion onboarding-hours" style="margin-top:18px" ${draft.prepExpanded?'open':''}><summary>Onboarding hours <span>${draft.prepBudget==='Separate onboarding effort'?'Separate from monthly hours':'Included in first month'} <span aria-hidden="true">⌄</span></span></summary><div class="inner"><p class="onboarding-question">How should strategy preparation count?</p><div class="onboarding-options" role="group" aria-label="Onboarding hours allocation">${[['Separate onboarding effort','Separate from monthly hours','Track preparation separately.'],['First delivery cycle SEO budget','Included in first month','Deduct preparation from the first month’s SEO hours.']].map(([value,label,description])=>`<button type="button" class="onboarding-choice" data-prep-budget="${value}" aria-pressed="${draft.prepBudget===value}"><span class="choice-indicator" aria-hidden="true"></span><span class="choice-copy"><span class="choice-title">${label}</span><span class="choice-description">${description}</span></span></button>`).join('')}</div><p class="onboarding-footnote">Monthly delivery begins on the Launched Date.</p></div></details>`;}

function custom(){return `<div class="fields">${select('SEO plan','plan',['Local SEO launch','Technical cleanup','Blank plan'],'Create from an existing template or start blank.')}${input('Estimated total hours','budget','number','Optional capacity estimate; not a monthly quota.','min="0" step="0.5"')}${input('Target completion','end','date','Optional for task-only projects.')}</div><div class="source-tabs">${[['plan','From SEO plan'],['manual','Custom tasks'],['basecamp','Basecamp import']].map(([id,name])=>`<button data-source="${id}" class="${draft.source===id?'selected':''}">${name}</button>`).join('')}</div>${draft.source==='plan'?`<p class="section-copy">Choose the tasks to carry over from the plan.</p>${draft.plan==='Blank plan'?'<p class="muted">Start with custom tasks or import an existing Basecamp list.</p>':(draft.plan==='Technical cleanup'?[planTasks[0],planTasks[2]]:planTasks).map(t=>taskChoice(t,'plan')).join('')}`:draft.source==='manual'?`<p class="section-copy">Add a specific piece of work to this client’s delivery queue.</p><div class="inline-add"><input id="new-task" aria-label="Custom task title" placeholder="e.g. Fix service-page titles"><button data-action="add-task">＋ Add task</button></div>${draft.manual.map(t=>`<div class="task"><span class="grow">${safe(t.title)}</span><span class="badge">Custom</span><button aria-label="Remove ${safe(t.title)}" data-remove="${t.id}">×</button></div>`).join('')}`:`<div class="import-box"><label class="field">Basecamp project<select data-field="project"><option>Evergreen Dental · SEO</option><option>Evergreen Dental · Website launch</option></select></label><p>Preview and select tasks. Import happens after the client exists.</p><button data-action="load-basecamp">${draft.basecampLoaded?'Refresh preview':'Preview Basecamp tasks'}</button>${draft.basecampLoaded?basecampTasks.map(t=>taskChoice(t,'basecamp')).join(''):''}</div>`}<div class="review-row" style="margin-top:14px"><span>Selected work</span><b>${tasks().length} tasks · ${tasks().reduce((n,t)=>n+(t.hours||0),0)} estimated hours</b></div>`;}
function taskChoice(t,source){return `<label class="task"><input type="checkbox" data-task="${t.id}" data-source-type="${source}" ${draft[source==='plan'?'planIds':'basecampIds'].includes(t.id)?'checked':''}><span class="grow">${safe(t.title)}</span><small>${t.hours}h</small></label>`;}
function summaryRows(c=draft){return `<div class="review-row"><span>Client</span><b>${safe(c.name||'New client')}</b></div><div class="review-row"><span>Engagement</span><b>${c.mode}</b></div><div class="review-row"><span>Account manager</span><b>${safe(c.owner)}</b></div>${c.mode==='Monthly'?`<div class="review-row"><span>${c.hoursCommitment==='committed_hours'?'SEO commitment':'SEO capacity'}</span><b>${c.hoursCommitment==='capacity'?`${c.hours}-hour monthly allowance`:`${c.hours} hours/month committed`}</b></div><div class="review-row"><span>Content</span><b>${c.content} content ${c.content===1?'piece':'pieces'} / month</b></div><div class="review-row"><span>GBP management</span><b>${c.gbp?'Optimization + Management':'Not included'}</b></div>`:`<div class="review-row"><span>SEO plan</span><b>${safe(c.plan)}</b></div><div class="review-row"><span>Delivery tasks</span><b>${c.tasks?c.tasks.length:tasks().length} selected</b></div><div class="review-row"><span>Capacity estimate</span><b>${c.budget||'—'} total hours</b></div>`}<div class="review-row"><span>Directory Listings</span><b>${c.mode==='Monthly'&&c.listings?'Setup + managed listings':'Not included'}</b></div><div class="review-row"><span>Onboarding effort</span><b>${safe(c.prepBudget)}</b></div><div class="review-row"><span>Launched Date</span><b>${c.launch?safe(c.launch):'Not launched'}</b></div><div class="review-row"><span>Status</span><b>Onboarding</b></div>`;}
function review(){return `<p class="section-title">Ready to create ${safe(draft.name||'your client')}?</p><p class="section-copy">Client details and the selected delivery scope will be saved together.</p><div class="review">${summaryRows()}</div><div class="callout">${draft.mode==='Monthly'?'Create planned service scope and onboarding tasks. Effort tracking starts now; recurring targets start at confirmed launch.':'Create the SEO plan and selected tasks. Basecamp selections are imported after client creation, with retry available for any failures.'}</div>`;}
function summaryPanel(){return `<aside class="summary-panel"><h3>Setup preview</h3><span class="badge pink">${draft.mode}</span><div class="stat">${draft.mode==='Monthly'?draft.hours+'h':tasks().length}</div><p>${draft.mode==='Monthly'?(draft.hoursCommitment==='committed_hours'?'Hours/month committed':'Monthly allowance'):'Tasks ready to add'}</p><div class="review-row"><span>Content</span><b>${draft.mode==='Monthly'?draft.content+' / month':'Scoped by plan'}</b></div><div class="review-row"><span>GBP</span><b>${draft.mode==='Monthly'&&draft.gbp?'Optimization + Management':'Not included'}</b></div><div class="review-row"><span>Listings</span><b>${draft.mode==='Monthly'&&draft.listings?'Setup + management':'Not included'}</b></div><ul>${draft.mode==='Monthly'?'<li>Service scope saved as planned</li><li>Log onboarding effort immediately</li><li>Recurring targets start at launch</li>':'<li>Draft plan initialized</li><li>Selected work added once</li><li>Basecamp import can be retried</li>'}</ul><p>Portal invites and account access can be completed later from the existing workspace.</p></aside>`;}
function success(){return `<div class="success"><div class="check">✓</div><h3>${safe(draft.created.name)} is ready</h3><p>Client created in this demo. Continue in the existing workspace.</p><div class="review output">${summaryRows(draft.created)}</div></div>`;}
function modal(content,kind='stepper',footer=''){return `<div class="overlay"><section class="modal ${kind}" role="dialog" aria-modal="true" aria-labelledby="setup-title"><header class="modal-header"><div><h2 id="setup-title">${draft.created?'Client setup complete':'New client setup'}</h2><p>${draft.created?'Your scope and selected work are ready.':'Start with the engagement, then configure the work.'}</p></div><button class="close" data-action="close" aria-label="Close setup">×</button></header><div class="body">${content}${draft.error?`<div class="error" role="alert">${safe(draft.error)}</div>`:''}</div><footer class="modal-footer">${footer||`<span class="footnote">Local demo · no records sent</span><div class="buttons"><button data-action="close">Close</button><button class="primary" data-action="view" data-view="${draft.mode==='Custom'?'SEO Plan':'Overview'}">Open ${draft.mode==='Custom'?'SEO Plan':'client'} →</button></div>`}</footer></section></div>`;}
function footer(next='Continue →',action='next'){return `<span class="footnote">Draft kept while this preview is open</span><div class="buttons"><button data-action="${draft.step>0?'back':'close'}">${draft.step>0?'← Back':'Cancel'}</button><button class="primary" data-action="${action}">${next}</button></div>`;}
function validate(stage){if(stage===1||stage==='all'){if(!draft.name.trim())return 'Enter a client name to continue.';if(!draft.start)return 'Choose an onboarding start date.';if(draft.launch&&draft.launch<draft.start)return 'Launched Date cannot be earlier than Onboarding Date.';if(draft.website){try{let u=new URL(draft.website);if(!['https:','http:'].includes(u.protocol))return 'Use an http:// or https:// website URL.'}catch{return 'Enter a full website URL, such as https://evergreendental.com.'}}}if(stage===2||stage==='all'){if(draft.mode==='Monthly'){if(!['committed_hours','capacity'].includes(draft.hoursCommitment))return 'Choose an hours commitment.';if(!Number.isFinite(draft.hours)||draft.hours<0)return 'SEO hours must be zero or greater.';if(!Number.isInteger(draft.content)||draft.content<0)return 'Content pieces must be a whole number, zero or greater.';if(!draft.hours&&!draft.content&&!draft.gbp&&!draft.listings)return 'Choose at least one monthly service.'}else{if(!Number.isFinite(draft.budget)||draft.budget<0)return 'Total estimated hours must be zero or greater.';if(draft.end&&draft.end<draft.start)return 'Target completion must follow the engagement start.';if(draft.plan==='Blank plan'&&!tasks().length)return 'Add at least one custom task or Basecamp task, or choose a plan template.'}}return '';}
function create(){draft.error=validate('all');if(draft.error){rerender();return}draft.created={...draft,name:draft.name.trim(),tasks:draft.mode==='Custom'?tasks().map(t=>({...t})):[{id:'setup-strategy',title:'Prepare SEO strategy and roadmap',hours:0},...(draft.gbp?[{id:'setup-gbp',title:'Complete initial GBP optimization',hours:0}]:[]),...(draft.listings?[{id:'setup-listings',title:'Activate directory listings and verify business information',hours:0}]:[])],plan:draft.mode==='Monthly'?'Monthly SEO plan':draft.plan};draft.savedClient=draft.created;rerender();}
function taskUpdate(id,source,checked){let key=source==='plan'?'planIds':'basecampIds';draft[key]=checked?[...new Set([...draft[key],id])]:draft[key].filter(v=>v!==id);}
document.addEventListener('input',e=>{if(e.target.dataset.field){let key=e.target.dataset.field;draft[key]=e.target.type==='number'?Number(e.target.value):e.target.value;draft.error='';const panel=document.querySelector('.summary-panel');if(panel)panel.outerHTML=summaryPanel();}});
document.addEventListener('change',e=>{if(e.target.hasAttribute('data-allowance')){draft.hoursCommitment=e.target.checked?'capacity':'committed_hours';draft.error='';rerender();document.querySelector('[data-allowance]')?.focus();}if(e.target.dataset.field){let key=e.target.dataset.field;draft[key]=e.target.type==='checkbox'?e.target.checked:e.target.type==='number'?Number(e.target.value):e.target.value;draft.error='';if(key==='plan'&&draft.plan==='Technical cleanup')draft.planIds=draft.planIds.filter(id=>id!=='research');if(key==='project'){draft.basecampLoaded=false;draft.basecampIds=[]}if(['hoursCommitment','gbp','gbpHours','gbpPosting','listings','prepBudget','plan','project'].includes(key))rerender();}if(e.target.dataset.task){taskUpdate(e.target.dataset.task,e.target.dataset.sourceType,e.target.checked);rerender();}});
document.addEventListener('click',e=>{if(e.target.closest('.onboarding-hours summary')){draft.prepExpanded=!e.target.closest('details').open;}let b=e.target.closest('button');if(!b)return;if(b.dataset.prepBudget){draft.prepBudget=b.dataset.prepBudget;draft.prepExpanded=true;rerender();document.querySelector(`[data-prep-budget="${draft.prepBudget}"]`)?.focus();}if(b.dataset.mode){draft.mode=b.dataset.mode;draft.error='';rerender()}if(b.dataset.source){draft.source=b.dataset.source;rerender()}if(b.dataset.remove){draft.manual=draft.manual.filter(t=>t.id!==b.dataset.remove);rerender()}let a=b.dataset.action;if(a==='open'){draft.open=true;draft.step=0;draft.created=null;draft.error='';rerender()}if(a==='close'){draft.open=false;rerender();document.querySelector('[data-action="open"]')?.focus()}if(a==='back'){draft.step=current===0?Math.max(0,draft.step-1):0;draft.error='';rerender()}if(a==='next'){draft.error=validate(draft.step);if(!draft.error)draft.step++;rerender();document.querySelector('.modal h2')?.scrollIntoView({block:'nearest'})}if(a==='create')create();if(a==='load-basecamp'){draft.basecampLoaded=true;rerender()}if(a==='add-task'){let field=document.getElementById('new-task');if(!field.value.trim()){draft.error='Enter a task title before adding it.';rerender();return}draft.manual.push({id:'manual-'+Date.now(),title:field.value.trim(),hours:0});draft.error='';rerender()}if(a==='view'){draft.open=false;draft.view=b.dataset.view||'Overview';rerender()}if(a==='list'){draft.view='list';rerender()}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&draft.open){draft.open=false;rerender();document.querySelector('[data-action="open"]')?.focus()}if(e.key==='Enter'&&e.target.id==='new-task'){e.preventDefault();document.querySelector('[data-action="add-task"]')?.click()}if(e.key==='Tab'&&draft.open){let controls=[...document.querySelectorAll('.modal button,.modal input,.modal select,.modal textarea,.modal summary,.proto-picker button')].filter(el=>el.getClientRects().length&&!el.disabled);if(e.shiftKey&&document.activeElement===controls[0]){e.preventDefault();controls.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===controls.at(-1)){e.preventDefault();controls[0].focus()}}});
